import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { Hub } from '../src/hub.mjs';
import { setup, content, skill } from './helpers.mjs';
import { digest, tree, treeHash, exists } from '../src/files.mjs';
import { targetPath, detect } from '../src/adapters.mjs';

test('read-only imports preserve originals; index rebuilds after restart', async t => {
  const { hub, config, dir, item } = await setup(t, false);
  const before = treeHash(await tree(dir));
  await assert.rejects(hub.preview('save', { id: item.id, expected: item.contentHash, text: content() }), { code: 'READ_ONLY' });
  const reopened = await new Hub(config).init();
  assert.equal((await reopened.scan()).skills[0].id, item.id);
  assert.equal(treeHash(await tree(dir)), before);
});
test('save previews, conflicts, validation and single-use confirmation', async t => {
  const { hub, item, dir } = await setup(t);
  const args = { id: item.id, expected: item.contentHash, text: content('sample', '# Changed') };
  const plan = await hub.preview('save', args);
  assert.equal(plan.before, content());
  await assert.rejects(hub.confirm(plan.id, false), { code: 'CONFIRMATION' });
  await hub.confirm(plan.id, true);
  assert.equal(await fs.readFile(path.join(dir, 'SKILL.md'), 'utf8'), args.text);
  await assert.rejects(hub.confirm(plan.id, true), { code: 'PLAN' });
  await assert.rejects(hub.preview('save', args), { code: 'CHANGED' });
  const current = await hub.detail(item.id);
  await assert.rejects(hub.preview('save', { ...args, expected: current.contentHash, text: '# invalid' }), { code: 'VALIDATION' });
  const next = await hub.preview('save', { ...args, expected: current.contentHash });
  await fs.writeFile(path.join(dir, 'SKILL.md'), content('sample', '# External'));
  await assert.rejects(hub.confirm(next.id, true), { code: 'CHANGED' });
});
for (const agent of ['pi', 'codex', 'claude']) test(`${agent}: full directory install, update, rollback, uninstall and restart`, async t => {
  const { hub, item, dir, config, targets } = await setup(t);
  await fs.mkdir(path.join(dir, 'references'));
  await fs.writeFile(path.join(dir, 'references', 'guide.md'), 'reference');
  await hub.scan();
  const install = await hub.preview('install', { id: item.id, target: agent });
  assert.equal(install.changes.length, 2);
  await hub.confirm(install.id, true);
  const dest = path.join(targets.find(x => x.id === agent).path, 'sample');
  assert.equal(treeHash(await tree(dest)), treeHash(await tree(dir)));
  await fs.writeFile(path.join(dir, 'SKILL.md'), content('sample', '# Version 2', '2.0'));
  await hub.scan();
  assert.equal((await hub.list())[0].installations.find(x => x.target === agent).state, 'update-available');
  const update = await hub.preview('install', { id: item.id, target: agent });
  await hub.confirm(update.id, true);
  const reopened = await new Hub(config).init(); await reopened.scan();
  const rollback = await reopened.preview('rollback', { id: item.id, target: agent });
  await reopened.confirm(rollback.id, true);
  assert.equal(await fs.readFile(path.join(dest, 'SKILL.md'), 'utf8'), content());
  const uninstall = await reopened.preview('uninstall', { id: item.id, target: agent });
  await reopened.confirm(uninstall.id, true);
  assert.equal(await exists(dest), false);
  const restore = await reopened.preview('restore-install', { id: item.id, target: agent });
  await reopened.confirm(restore.id, true);
  assert.equal(await fs.readFile(path.join(dest, 'SKILL.md'), 'utf8'), content());
  assert.equal(await fs.readFile(path.join(dir, 'SKILL.md'), 'utf8'), content('sample', '# Version 2', '2.0'));
});
test('tampered backup is never restored', async t => {
  const { hub, item, dir } = await setup(t);
  let plan = await hub.preview('install', { id: item.id, target: 'pi' }); await hub.confirm(plan.id, true);
  await fs.writeFile(path.join(dir, 'SKILL.md'), content('sample', '# next')); await hub.scan();
  plan = await hub.preview('install', { id: item.id, target: 'pi' }); await hub.confirm(plan.id, true);
  const record = hub.records['pi/sample'];
  await fs.writeFile(path.join(record.backup, 'SKILL.md'), 'tampered');
  await assert.rejects(hub.preview('rollback', { id: item.id, target: 'pi' }), { code: 'BACKUP' });
});
test('unmanaged conflicts and modified managed files never overwritten; adapters isolated', async t => {
  const { hub, item, targets } = await setup(t);
  const target = path.join(targets[0].path, 'sample');
  await fs.mkdir(target); await fs.writeFile(path.join(target, 'user.txt'), 'mine');
  await assert.rejects(hub.preview('install', { id: item.id, target: 'pi' }), { code: 'CONFLICT' });
  const good = await hub.preview('install', { id: item.id, target: 'codex' });
  await hub.confirm(good.id, true);
  const installed = path.join(targets[1].path, 'sample', 'SKILL.md');
  await fs.writeFile(installed, 'user edit');
  await assert.rejects(hub.preview('uninstall', { id: item.id, target: 'codex' }), { code: 'CONFLICT' });
  assert.equal(await fs.readFile(installed, 'utf8'), 'user edit');
});
test('stale sources, target races and expired plans fail without leftovers', async t => {
  const { hub, item, dir, targets } = await setup(t);
  const plan = await hub.preview('install', { id: item.id, target: 'pi' });
  await fs.writeFile(path.join(dir, 'SKILL.md'), content('sample', 'changed'));
  await assert.rejects(hub.confirm(plan.id, true), { code: 'CHANGED' });
  await hub.scan();
  const race = await hub.preview('install', { id: item.id, target: 'pi' });
  await fs.mkdir(path.join(targets[0].path, 'sample'));
  await assert.rejects(hub.confirm(race.id, true), { code: 'CHANGED' });
  const expired = await hub.preview('install', { id: item.id, target: 'claude' });
  hub.plans.get(expired.id).expires = 0;
  await assert.rejects(hub.confirm(expired.id, true), { code: 'PLAN' });
  assert.deepEqual(await fs.readdir(targets[2].path), []);
});
test('failed record persistence restores prior disk state and retains traceable backup', async t => {
  const { hub, item, dir, targets } = await setup(t);
  let plan = await hub.preview('install', { id: item.id, target: 'pi' }); await hub.confirm(plan.id, true);
  await fs.writeFile(path.join(dir, 'SKILL.md'), content('sample', '# new'));
  await hub.scan(); plan = await hub.preview('install', { id: item.id, target: 'pi' });
  const persist = hub.persist.bind(hub);
  let fail = true;
  hub.persist = async () => { if (fail) { fail = false; const error = new Error('denied'); error.code = 'EACCES'; throw error; } return persist(); };
  await assert.rejects(hub.confirm(plan.id, true), { code: 'EACCES' });
  assert.equal(await fs.readFile(path.join(targets[0].path, 'sample', 'SKILL.md'), 'utf8'), content());
  assert.equal((await fs.readdir(targets[0].path)).filter(x => x.startsWith('.skill-hub')).length, 0);
});
test('interrupted journal survives restart and blocks only affected target', async t => {
  const { hub, config, item } = await setup(t);
  await fs.writeFile(path.join(config.state, 'transaction-test.json'), JSON.stringify({ key: 'pi/sample' }));
  const reopened = await new Hub(config).init();
  const result = await reopened.scan();
  assert.deepEqual(result.interrupted, ['pi/sample']);
  await assert.rejects(reopened.preview('install', { id: item.id, target: 'pi' }), { code: 'INTERRUPTED' });
  assert.ok(await reopened.preview('install', { id: item.id, target: 'claude' }));
});
test('hundreds of skills, duplicate detection, missing SKILL.md and root failure isolation', async t => {
  const { config, root } = await setup(t);
  await Promise.all(Array.from({ length: 220 }, (_, i) => skill(root, `skill-${i}`)));
  const second = path.join(path.dirname(root), 'other'); await fs.mkdir(second); await skill(second);
  config.roots.push({ id: 'other', path: second }, { id: 'gone', path: path.join(path.dirname(root), 'missing') });
  await fs.mkdir(path.join(root, 'broken', 'scripts'), { recursive: true });
  const hub = await new Hub(config).init();
  const start = Date.now(); const result = await hub.scan();
  assert.equal(result.skills.length, 223);
  assert.ok(result.skills.find(x => x.name === 'sample').issues.some(x => x.code === 'DUPLICATE_NAME'));
  assert.ok(result.skills.find(x => x.name === 'broken').issues.some(x => x.severity === 'error'));
  assert.equal(result.errors[0].root, 'gone');
  t.diagnostic(`Scanned ${result.skills.length} Skills in ${Date.now() - start} ms`);
});
test('adapter paths, failed version detection and unknown loading state', async () => {
  const home = path.resolve('home'), project = path.resolve('project');
  assert.equal(targetPath('pi', 'user', project, home), path.join(home, '.pi', 'agent', 'skills'));
  assert.equal(targetPath('codex', 'project', project), path.join(project, '.agents', 'skills'));
  assert.equal(targetPath('claude', 'project', project), path.join(project, '.claude', 'skills'));
  const result = await detect('pi', path.resolve('missing-pi.exe'));
  assert.equal(result.available, false); assert.equal(result.loaded, null);
});
test('overlapping source, state and target paths are rejected', async t => {
  const { config } = await setup(t);
  config.targets[0].path = config.roots[0].path;
  assert.throws(() => new Hub(config), { code: 'CONFIG' });
});
test('draft preview never creates files before confirmation', async t => {
  const { hub, root } = await setup(t);
  const plan = await hub.preview('draft', { root: 'source', name: 'from-note', text: '# Note content' });
  assert.equal(await exists(path.join(root, 'from-note')), false);
  await hub.confirm(plan.id, true);
  assert.ok((await hub.scan()).skills.some(x => x.name === 'from-note'));
});
